export const notes=[
 "الأصل: «البؤساء» (Les Misérables) لفيكتور هوغو، 1862، من التراث العامّ. اختصرنا الرواية (خمسة أجزاء ونحو 1500 صفحة) في ستة فصول تتبع جان فالجان من 1815 إلى 1833.",
 "من النصّ: كلّ بطاقةٍ عنوانها «من نصّ هوغو» ترجمتُنا لسطرٍ من الأصل الفرنسي، والأصلُ تحتها، مع مصدرين: مشروع غوتنبرغ (17489 و17519) وويكي مصدر الفرنسي.",
 "كما في الرواية: الجواز الأصفر والرغيف والسنوات التسع عشرة، والمطران ميرييل وفضّته وشمعداناه، وبُتي جرفيه وقطعة الأربعين سو، ومونتروي ومصنع الخرز الأسود، وعربة فوشلفان، ومأساة فانتين وكرة الثلج، واعتراف أرّاس وتفاصيل السجناء الثلاثة، وموت فانتين، والسقوط من السفينة أوريون، والدلو والدمية «كاترين»، وثمن كوزيت، والجدار والدير، وحديقة اللوكسمبورغ، وفخّ بيت غوربو والإزميل المحمرّ، والورقة النشّافة والمرآة، والحاجز وغافروش، والعفو عن جافير، والمجاري، وقطعة المعطف، والعرس والإبهام المربوط، والاعتراف لماريوس، والموت في ضوء الشمعدانين، والأبيات على القبر.",
 "مختصر: حذفنا فصولًا كثيرة (واترلو، والدير بتفصيله، وأصدقاء «أ ب ث»، وإيبونين بتفصيلها)، وضممنا بعض الأحداث، ونقلنا ثوبَ الحداد إلى صورة البيت.",
 "ماذا لو؟ ثلاث نهايات ليست في الرواية، تبدأ بسطر «هنا تخرج الحكاية عن رواية هوغو»: السكوت في أرّاس، وإحراق الرسالة، وكتمان السرّ عن ماريوس.",
 "متخيَّل: اختيارات القارئ وبعض العبارات الصغيرة في الحوار. وما همسَ به جان فالجان لفانتين لم يذكره هوغو، فتركناه سرًّا كما في الرواية."
];
